settings.custom_code:
{% assign ball_tables = product.metafields.custom.ball_comparison.value %}

{% if ball_tables %}
  <style>
    /*
     * SECTION WRAPPER
     * Consistent top margin with other spec components on the page.
     */
    .ball-comparison {
      margin-top: 48px;
    }

    .ball-comparison__table {
      margin-top: 32px;
    }

    /*
     * SCROLL CONTAINER
     * Refined scrollbar — minimal and unobtrusive.
     */
    .ball-comparison__scroll {
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }

    .ball-comparison__scroll::-webkit-scrollbar { height: 4px; }
    .ball-comparison__scroll::-webkit-scrollbar-thumb { background: #ccc; border-radius: 999px; }
    .ball-comparison__scroll::-webkit-scrollbar-track { background: transparent; }

    /*
     * CARD GRID
     * align-items: start prevents cards from stretching to match
     * each other — fixes uneven row heights when content varies.
     */
    .ball-comparison__grid {
      display: flex;
      gap: 16px;
      padding-bottom: 8px;
      align-items: start;
    }

    @media screen and (min-width: 990px) {
      .ball-comparison__grid {
        justify-content: center;
      }
    }

    /*
     * CARD
     * Hairline border, no radius — architectural and precise.
     */
    .ball-comparison__card {
      flex: 0 0 300px;
      display: flex;
      flex-direction: column;
      border: 1px solid #e8e8e8;
    }

    /*
     * TITLE IMAGE AREA
     * Black header band — compact brand anchor.
     */
    .ball-comparison__title-image {
      background: #000;
      padding: 10px 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 56px;
    }

    .ball-comparison__title-image img {
      max-width: 70%;
      max-height: 36px;
      width: auto;
      height: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /*
     * PRODUCT IMAGE AREA
     * Neutral grey field, consistent padding.
     */
    .ball-comparison__product-image {
      background: #f2f2f2;
      padding: 24px;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .ball-comparison__product-image img {
      max-width: 100%;
      height: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /*
     * SPECS BLOCK
     * Top border separates from product image zone.
     */
    .ball-comparison__specs {
      margin-top: 0;
      border-top: 1px solid #e8e8e8;
    }

    /*
     * SPEC ROWS
     * Switched from flex with fixed percentages to grid with auto columns.
     * This lets the value column expand naturally without spilling — the
     * root fix for the text overflow issue on rows with longer content
     * like performance updates and rating bars.
     */
    .ball-comparison__row {
      display: grid;
      grid-template-columns: auto 1fr;
      align-items: start;
      padding: 14px 20px;
      border-bottom: 1px solid #e8e8e8;
      column-gap: 16px;
      transition: background 0.18s ease, box-shadow 0.18s ease;
    }

    .ball-comparison__row:nth-child(odd)  { background: #fff; }
    .ball-comparison__row:nth-child(even) { background: #fafafa; }

    .ball-comparison__row:last-child {
      border-bottom: none;
    }

    .ball-comparison__row:hover {
      background: #f2f2f2;
      box-shadow: inset 3px 0 0 #000;
    }

    /*
     * ROW LABEL
     * All-caps, wide tracking — matches spec table first-child cells.
     * white-space: nowrap keeps it on one line so grid sizing is stable.
     */
    .ball-comparison__label {
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: #000;
      white-space: nowrap;
      padding-top: 2px;
    }

    /*
     * ROW VALUE
     * Takes remaining width via 1fr. Text wraps naturally within
     * the available space — no more spill.
     */
    .ball-comparison__value {
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 13px;
      font-weight: 400;
      letter-spacing: 0.02em;
      color: #222;
      text-align: right;
      white-space: normal;
      word-break: break-word;
      overflow-wrap: anywhere;
      line-height: 1.5;
      text-transform: none;
    }

    /*
     * RATING BARS
     * Black on/off — consistent with the black/grey palette.
     */
    .ball-comparison__rating {
      display: inline-flex;
      gap: 3px;
      justify-content: flex-end;
      align-items: center;
      flex-wrap: nowrap;
    }

    .ball-comparison__seg {
      width: 10px;
      height: 18px;
      background: #e0e0e0;
      display: inline-block;
      flex-shrink: 0;
    }

    .ball-comparison__seg.is-on {
      background: #000;
    }

    /*
     * COLORWAY SWATCHES
     * Slightly larger, cleaner border — refined but still functional.
     */
    .ball-comparison__swatches {
      display: inline-flex;
      gap: 6px;
      justify-content: flex-end;
      align-items: center;
      flex-wrap: wrap;
    }

    .ball-comparison__swatch {
      width: 14px;
      height: 14px;
      border-radius: 999px;
      border: 1px solid #bbb;
      display: inline-block;
      flex-shrink: 0;
    }

    /*
     * PERFORMANCE UPDATES LIST
     * Left-aligned, normal case — readable without competing with labels.
     * Negative margin pulls it flush with the value column alignment.
     */
    .ball-comparison__updates {
      margin: 0;
      padding-left: 16px;
      text-transform: none;
      letter-spacing: 0;
      text-align: left;
      font-size: 13px;
      line-height: 1.6;
      color: #333;
    }

    .ball-comparison__updates li {
      margin: 4px 0;
    }

    /*
     * DIAGRAM IMAGE
     * Clean separation below the spec rows.
     */
    .ball-comparison__diagram {
      padding: 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      border-top: 1px solid #e8e8e8;
    }

    .ball-comparison__diagram img {
      max-width: 100%;
      height: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /*
     * RESPONSIVE
     * Cards shrink slightly on mobile; padding pulled in.
     */
    @media (max-width: 768px) {
      .ball-comparison__card {
        flex: 0 0 260px;
      }

      .ball-comparison__row {
        padding: 12px 14px;
      }

      .ball-comparison__label { font-size: 10px; }
      .ball-comparison__value { font-size: 12px; }
    }
  </style>

  {% for table in ball_tables %}
    {% assign rows = table.rows.value %}
    {% if rows == blank %}
      {% assign rows = table.rows %}
    {% endif %}

    <section class="ball-comparison__table ball-comparison">
      {% if rows %}
        <div class="ball-comparison__scroll">
          <div class="ball-comparison__grid">

            {% for row in rows %}
              <div class="ball-comparison__card">

                {% if row.title_image %}
                  <div class="ball-comparison__title-image">
                    {{ row.title_image | image_url: width: 600 | image_tag: loading: 'lazy' }}
                  </div>
                {% endif %}

                {% if row.product_image %}
                  <div class="ball-comparison__product-image">
                    {{ row.product_image | image_url: width: 900 | image_tag: loading: 'lazy' }}
                  </div>
                {% endif %}

                <div class="ball-comparison__specs">
                  {% if row.construction != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Construction</span>
                      <span class="ball-comparison__value">{{ row.construction }}</span>
                    </div>
                  {% endif %}

                  {% if row.compression != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Compression</span>
                      <span class="ball-comparison__value">{{ row.compression }}</span>
                    </div>
                  {% endif %}

                  {% if row.feel != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Feel</span>
                      <span class="ball-comparison__value">{{ row.feel }}</span>
                    </div>
                  {% endif %}

                  {% if row.flight != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Flight</span>
                      <span class="ball-comparison__value">{{ row.flight }}</span>
                    </div>
                  {% endif %}

                  {% if row.distance != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Distance</span>
                      <span class="ball-comparison__value">
                        {% assign v = row.distance.rating | default: row.distance.value.rating | default: row.distance | round %}
                        {% assign v = v | at_least: 0 | at_most: 6 %}
                        <span class="ball-comparison__rating" aria-label="Distance rating {{ v }}">
                          {% for i in (1..6) %}
                            <span class="ball-comparison__seg{% if i <= v %} is-on{% endif %}"></span>
                          {% endfor %}
                        </span>
                      </span>
                    </div>
                  {% endif %}

                  {% if row.driver_spin != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Driver Spin</span>
                      <span class="ball-comparison__value">
                        {% assign v = row.driver_spin.rating | default: row.driver_spin.value.rating | default: row.driver_spin | round %}
                        {% assign v = v | at_least: 0 | at_most: 6 %}
                        <span class="ball-comparison__rating" aria-label="Driver spin rating {{ v }}">
                          {% for i in (1..6) %}
                            <span class="ball-comparison__seg{% if i <= v %} is-on{% endif %}"></span>
                          {% endfor %}
                        </span>
                      </span>
                    </div>
                  {% endif %}

                  {% if row.iron_spin != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Iron Spin</span>
                      <span class="ball-comparison__value">
                        {% assign v = row.iron_spin.rating | default: row.iron_spin.value.rating | default: row.iron_spin | round %}
                        {% assign v = v | at_least: 0 | at_most: 6 %}
                        <span class="ball-comparison__rating" aria-label="Iron spin rating {{ v }}">
                          {% for i in (1..6) %}
                            <span class="ball-comparison__seg{% if i <= v %} is-on{% endif %}"></span>
                          {% endfor %}
                        </span>
                      </span>
                    </div>
                  {% endif %}

                  {% if row.greenside_spin != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Greenside Spin</span>
                      <span class="ball-comparison__value">
                        {% assign v = row.greenside_spin.rating | default: row.greenside_spin.value.rating | default: row.greenside_spin | round %}
                        {% assign v = v | at_least: 0 | at_most: 6 %}
                        <span class="ball-comparison__rating" aria-label="Greenside spin rating {{ v }}">
                          {% for i in (1..6) %}
                            <span class="ball-comparison__seg{% if i <= v %} is-on{% endif %}"></span>
                          {% endfor %}
                        </span>
                      </span>
                    </div>
                  {% endif %}

                  {% assign color_list = row.colorways.value %}
                  {% if color_list == blank %}
                    {% assign color_list = row.colorways %}
                  {% endif %}

                  {% if color_list %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Colorways</span>
                      <span class="ball-comparison__value">
                        <span class="ball-comparison__swatches">
                          {% for c in color_list %}
                            {% assign c_clean = c | strip %}
                            {% if c_clean != blank %}
                              {% assign c_down = c_clean | downcase %}

                              {% assign p1 = c_down %}
                              {% assign p2 = '' %}
                              {% if c_down contains '/' %}
                                {% assign parts = c_down | split: '/' %}
                                {% assign p1 = parts[0] | strip %}
                                {% assign p2 = parts[1] | strip %}
                              {% endif %}

                              {% assign col1 = '#ffffff' %}
                              {% if p1 contains 'black' %}{% assign col1 = '#000000' %}
                              {% elsif p1 contains 'red' %}{% assign col1 = '#E60021' %}
                              {% elsif p1 contains 'yellow' %}{% assign col1 = '#ffdd00' %}
                              {% elsif p1 contains 'orange' %}{% assign col1 = '#ff6a00' %}
                              {% elsif p1 contains 'pink' %}{% assign col1 = '#ff4da6' %}
                              {% elsif p1 contains 'green' %}{% assign col1 = '#00a651' %}
                              {% elsif p1 contains 'blue' %}{% assign col1 = '#0072ce' %}
                              {% elsif p1 contains 'white' %}{% assign col1 = '#ffffff' %}
                              {% endif %}

                              {% assign bg = col1 %}
                              {% if p2 != blank %}
                                {% assign col2 = '#ffffff' %}
                                {% if p2 contains 'black' %}{% assign col2 = '#000000' %}
                                {% elsif p2 contains 'red' %}{% assign col2 = '#E60021' %}
                                {% elsif p2 contains 'yellow' %}{% assign col2 = '#ffdd00' %}
                                {% elsif p2 contains 'orange' %}{% assign col2 = '#ff6a00' %}
                                {% elsif p2 contains 'pink' %}{% assign col2 = '#ff4da6' %}
                                {% elsif p2 contains 'green' %}{% assign col2 = '#00a651' %}
                                {% elsif p2 contains 'blue' %}{% assign col2 = '#0072ce' %}
                                {% elsif p2 contains 'white' %}{% assign col2 = '#ffffff' %}
                                {% endif %}

                                {% assign bg = 'linear-gradient(90deg, ' | append: col1 | append: ' 0%, ' | append: col1 | append: ' 50%, ' | append: col2 | append: ' 50%, ' | append: col2 | append: ' 100%)' %}
                              {% endif %}

                              <span class="ball-comparison__swatch" style="background: {{ bg }};" aria-label="{{ c_clean }}"></span>
                            {% endif %}
                          {% endfor %}
                        </span>
                      </span>
                    </div>
                  {% endif %}

                  {% if row.performance_updates != blank %}
                    <div class="ball-comparison__row">
                      <span class="ball-comparison__label">Performance Updates</span>
                      <span class="ball-comparison__value">
                        <ul class="ball-comparison__updates">
                          {% assign lines = row.performance_updates | newline_to_br | split: '<br />' %}
                          {% for line in lines %}
                            {% assign t = line | strip %}
                            {% if t != blank %}
                              <li>{{ t }}</li>
                            {% endif %}
                          {% endfor %}
                        </ul>
                      </span>
                    </div>
                  {% endif %}
                </div>

                {% if row.diagram_image %}
                  <div class="ball-comparison__diagram">
                    {{ row.diagram_image | image_url: width: 1200 | image_tag: loading: 'lazy' }}
                  </div>
                {% endif %}

              </div>
            {% endfor %}

          </div>
        </div>
      {% endif %}
    </section>
  {% endfor %}
{% endif %}
